# Generated by KernelGen: https://github.com/flagos-ai/KernelGen
from typing import Generator

import pytest
import torch

from . import base

# Hardcoded shapes: affine_grid_generator_backward requires
# grad_output [N,H,W,2] + size [N,C,H,W]; CI --level core overrides
# GenericBenchmark shapes with 1D/3D defaults,
# so we use a custom Benchmark subclass with set_shapes override.
AFFINE_GRID_BACKWARD_SHAPES = [
    (1, 64, 64),
    (4, 128, 128),
    (8, 256, 256),
    (16, 64, 64),
    (32, 32, 32),
    (2, 512, 512),
]


class AffineGridBackwardBenchmark(base.Benchmark):
    def set_shapes(self, shape_file_path=None):
        self.shapes = AFFINE_GRID_BACKWARD_SHAPES
        self.shape_desc = "N, H, W"

    def get_input_iter(self, cur_dtype) -> Generator:
        for shape in self.shapes:
            N, H, W = shape
            grad_output = torch.randn((N, H, W, 2), dtype=cur_dtype, device=self.device)
            size = [N, 1, H, W]
            align_corners = True
            yield grad_output, size, align_corners


@pytest.mark.affine_grid_generator_backward
def test_affine_grid_generator_backward():
    bench = AffineGridBackwardBenchmark(
        op_name="affine_grid_generator_backward",
        torch_op=torch.ops.aten.affine_grid_generator_backward,
        # float32 only: kernel uses float32 accumulation internally
        dtypes=[torch.float32],
    )
    bench.run()
